    fun find(id: String): FriendProviderPreset? = presets.firstOrNull { it.id == id }

    fun canInfer(connection: FriendModelConnection): Boolean =
        connection.providerType !in setOf("onnx", "claude_subscription", "gemini_subscription") &&
            find(connection.providerId)?.inference != false
}
